//! Required BR clear DOMString reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><br id=para clear=MiXeD><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://br-clear.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn br_clear_canonical_accessor_descriptor_and_initial_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),P=HTMLBRElement.prototype,a=Object.getOwnPropertyDescriptor(P,'clear');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get clear'||a.set.name!=='set clear'||Object.hasOwn(x,'clear')||x.clear!=='MiXeD'||x.textContent!=='')throw 'canonical line break clear accessor';"#);}
#[test]
fn br_clear_native_domstring_aliases_old_values_and_absent_default(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),attr=x.getAttributeNode('clear'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.clear='A\ud800Z';var records=watch.takeRecords();if(x.clear!=='A\ud800Z'||attr.value!==x.clear||x.getAttributeNode('clear')!==attr||records.length!==1||records[0].attributeName!=='clear'||records[0].oldValue!=='MiXeD'||x.textContent!=='')throw 'exact line break clear transaction';attr.nodeValue='unrestricted';if(x.clear!=='unrestricted')throw 'ordinary string reflection';x.removeAttribute('clear');if(x.clear!==''||attr.ownerElement!==null||attr.value!=='unrestricted')throw 'removed clear default';x.clear=null;if(x.clear!=='null'||document.getElementById('neighbor').value!=='seed')throw 'null DOMString conversion';"#);}
#[test]
fn br_clear_inert_exact_namespace_once_conversion_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:br');if(!(x instanceof HTMLBRElement)||x.clear!=='')throw 'inert line break clear default';var calls=0;x.clear={toString:function(){calls++;x.setAttribute('clear','author');return 'R\udfffZ';}};if(calls!==1||x.clear!=='R\udfffZ'||x.getAttribute('clear')!==x.clear)throw 'once exact conversion';x.setAttributeNS('urn:foreign','clear','foreign');x.setAttributeNS(null,'ALIGN','upper');if(x.clear!=='R\udfffZ')throw 'exact null namespace clear';var clone=x.cloneNode(false);if(clone.clear!==x.clear)throw 'namespace copy';x.removeAttributeNS('urn:foreign','clear');x.removeAttributeNS(null,'ALIGN');var copy=document.importNode(x,false);if(copy.clear!==x.clear||copy.ownerDocument!==document||clone.getAttributeNode('clear')===x.getAttributeNode('clear'))throw 'actual copies';clone.clear='independent';if(x.clear!=='R\udfffZ'||copy.clear!=='R\udfffZ')throw 'independent copied clear';"#);}

#[test]
fn br_clear_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),old=x.getAttributeNode('clear'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.clear={toString:function(){calls++;x.removeAttribute('clear');x.setAttribute('clear','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('clear'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='MiXeD'||current.value!=='A\ud800Z'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.clear={toString:function(){x.setAttribute('clear','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.clear!=='author effect'||records.length!==1||records[0].oldValue!=='A\ud800Z')throw 'abrupt conversion preserves author effect';caught=false;try{x.clear=Symbol('div');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.clear!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.clear=value;if(x.clear!==String(value))throw 'ordinary DOMString conversion';}if(x.textContent!=='')throw 'metadata leaves displayed text';"#);
}

#[test]
fn br_clear_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),C=HTMLBRElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'clear'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('hr'),document.createElement('p'),document.createElement('h1'),document.createElement('div'),document.createElement('legend'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','br'),new Document().createElementNS('http://www.w3.org/1999/xhtml','BR')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'clear',{value:'author',writable:true,configurable:true});if(x.clear!=='author'||a.get.call(x)!=='MiXeD')throw 'canonical authority';a.set.call(x,'canonical');if(x.clear!=='author'||x.getAttribute('clear')!=='canonical')throw 'borrowed real setter';delete x.clear;if(x.clear!=='canonical'||Object.hasOwn(x,'clear'))throw 'restored inherited reflection';delete window.HTMLBRElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}

#[test]
fn br_clear_native_inert_attribute_aliases_namespace_and_exact_copies(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','br');x.setAttribute('clear','MiXeD');"}else{"var x=document.getElementById('para');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('clear');for(var writer of ['value','nodeValue','textContent']){a[writer]='R\ud800'+writer;if(x.clear!=='R\ud800'+writer||x.getAttributeNode('clear')!==a)throw 'exact attached alias';}x.setAttributeNS('urn:foreign','clear','foreign');x.setAttributeNS(null,'ALIGN','upper');if(x.clear!=='R\ud800textContent'||x.getAttributeNodeNS(null,'clear')!==a)throw 'exact null namespace/local name';x.setAttributeNS(null,'clear','no date parsing');if(x.clear!=='no date parsing'||a.value!==x.clear)throw 'exact null namespace writer';var copy=x.cloneNode(false);if(copy.clear!==x.clear||copy.getAttributeNode('clear')===a)throw 'independent clone';x.removeAttributeNS(null,'clear');if(x.clear!==''||a.ownerElement!==null||copy.clear!=='no date parsing')throw 'removed actual default';"#);}
}

#[test]
fn br_clear_native_adoption_and_return_keep_actual_interface_attr_and_child_handles(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),attr=x.getAttributeNode('clear'),first=x.firstChild,list=x.childNodes,C=HTMLBRElement,doc=new Document();if(doc.adoptNode(x)!==x||x.ownerDocument!==doc||x.parentNode!==null||!(x instanceof C)||x.clear!=='MiXeD'||attr.ownerElement!==x||attr.ownerDocument!==doc||x.firstChild!==first||x.childNodes!==list)throw 'actual native data adoption';x.clear='A\udfffZ';if(document.adoptNode(x)!==x||x.ownerDocument!==document||x.clear!=='A\udfffZ'||x.getAttributeNode('clear')!==attr)throw 'same native identity return';document.body.appendChild(x);if(x.firstChild!==first||x.childNodes!==list||x.textContent!==''||attr.value!==x.clear)throw 'reconnected data source';"#);
}

#[test]
fn br_clear_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLBRElement,a=Object.getOwnPropertyDescriptor(C.prototype,'clear'),calls=0;if(C===HTMLBRElement||a.get.call(x)!=='MiXeD')throw 'captured data accessor';"#);p.set_location(&crate::navigation::address("https://other-br-clear.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://br-clear.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'data origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.

#[test]
fn br_clear_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.clear='Long canonical \ud800 BR clear metadata replacement';",r"x.setAttribute('clear','Long canonical \ud800 BR clear metadata replacement');",r"attr.value='Long canonical \ud800 BR clear metadata replacement';",r"attr.nodeValue='Long canonical \ud800 BR clear metadata replacement';",r"attr.textContent='Long canonical \ud800 BR clear metadata replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','br');x.setAttribute('clear','MiXeD');"}else{"var x=document.getElementById('para');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('clear'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("value writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='MiXeD'||x.clear!=='MiXeD'||watch.takeRecords().length)throw 'atomic value writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.clear!=='Long canonical \ud800 BR clear metadata replacement'||records.length!==1||records[0].oldValue!=='MiXeD'||records[0].attributeName!=='clear'||x.getAttributeNode('clear')!==attr)throw 'fresh value writer recovery';");
 }}}
}

#[test]
fn br_clear_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var data=new Document().createElementNS('http://www.w3.org/1999/xhtml','br');data.clear='A\ud800Z';");let Value::Host(object)=p.runtime.execute("data;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert data handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('para').clear='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("para")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.br_clear_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.br_clear_get(object).is_ok());}}
}

#[test]
fn br_clear_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["br"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById('para');");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.clear='exact';");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.clear='exact';");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('clear');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('clear')!==oldValue||watch.takeRecords().length)throw 'atomic gauge lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('clear')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.clear!==source.clear||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}

#[test]
fn br_clear_reserved_main_connection_needs_no_additional_node_slots(){
 for tag in ["br"]{for inert_owner in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,owner={},source=owner.createElementNS('http://www.w3.org/1999/xhtml','{tag}');source.clear='exact';var first=source.firstChild,attr=source.getAttributeNode('clear');",if inert_owner{"new Document()"}else{"document"}));let nodes=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(target.appendChild(source)!==source||source.ownerDocument!==document||source.firstChild!==first||source.getAttributeNode('clear')!==attr||source.clear!=='exact'||source.parentNode!==target)throw 'reserved native gauge connection';");assert_eq!(d.nodes.len(),nodes);p.state.node_limit=limit;}}
}

#[test]
fn br_clear_void_native_copies_import_and_template_keep_actual_records(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('para');x.clear='A\ud800Z';var attr=x.getAttributeNode('clear'),copy=x.cloneNode(true),a=copy.getAttributeNode('clear');if(!(copy instanceof HTMLBRElement)||copy.clear!==x.clear||copy.firstChild!==null||x.firstChild!==null||copy.textContent!==''||a===attr)throw 'actual void deep clone';copy.clear='independent';if(x.clear!=='A\ud800Z'||attr.value!==x.clear)throw 'independent void metadata';var doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','t:br');source.clear='I\udfffZ';var imported=document.importNode(source,true);document.body.appendChild(imported);if(!(imported instanceof HTMLBRElement)||imported.clear!==source.clear||imported.firstChild!==null||imported.getAttributeNode('clear')===source.getAttributeNode('clear')||source.ownerDocument!==doc)throw 'actual void import';var leaf=imported.cloneNode(false),template=document.createElement('template');template.content.appendChild(leaf);document.body.appendChild(template);if(leaf.clear!==imported.clear||leaf.firstChild!==null||leaf.parentNode!==template.content||leaf.ownerDocument!==template.content.ownerDocument)throw 'actual void template parking';"#);
}

